uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// Parameter mappings
uniform float u_speed;
uniform float u_scale;
uniform float u_intensity;
uniform float u_color_cycle;
uniform float u_layers;

out vec4 fragColor;

// --- Helper Functions ---

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

vec2 hash22(vec2 p) {
    p = vec2(dot(p,vec2(127.1,311.7)), dot(p,vec2(269.5,183.3)));
    return fract(sin(p)*43758.5453) * 2.0 - 1.0;
}

float hash(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

// Polynomial smooth minimum for gooey merging
float smin(float a, float b, float k) {
    float h = max(k - abs(a - b), 0.0);
    return min(a, b) - h * h * 0.25 / k;
}

// Organic Fleshy Palette (Deep Reds, Pinks, Bioluminescent Cyans)
vec3 palette(float t) {
    vec3 a = vec3(0.5, 0.1, 0.2); 
    vec3 b = vec3(0.6, 0.3, 0.5); 
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.00, 0.20, 0.40);
    return a + b * cos(6.28318 * (c * t + d));
}

// Organic Blobs (Distance field with merging cells)
// Returns vec2: x = merged distance, y = mixed activation state
vec2 getOrganicBlobs(vec2 uv, float t) {
    vec2 n = floor(uv);
    vec2 f = fract(uv);

    float minDist = 8.0;
    float activation = 0.0;

    // Check surrounding grid cells for neighboring blobs
    for(int j=-1; j<=1; j++) {
        for(int i=-1; i<=1; i++) {
            vec2 g = vec2(float(i),float(j));
            vec2 rand = hash22(n + g) * 0.5 + 0.5; // 0 to 1

            // Organic orbital movement (blobs shifting around)
            vec2 pos = g + rand;
            pos.x += 0.4 * sin(t * 1.2 + rand.x * 10.0);
            pos.y += 0.4 * cos(t * 1.5 + rand.y * 10.0);

            float d = length(pos - f);

            // The magic: smooth merge with the previous closest distance
            minDist = smin(minDist, d, 0.45); 

            // Blend the activation signal based on how close we are to this cell
            float influence = exp(-d * 4.0);
            activation += hash(n + g) * influence;
        }
    }

    return vec2(minDist, activation);
}

void main() {
    // 1. Correct Aspect Ratio UVs
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;

    // 2. Timing
    float spd = (u_speed <= 0.0) ? 0.2 : u_speed;
    float t = iTime * spd;

    // --- Background (Fluid Tissue Plasm) ---
    vec3 bgTop = vec3(0.12, 0.02, 0.05); // Deep Blood Red
    vec3 bgBottom = vec3(0.04, 0.01, 0.08); // Dark bruised purple

    // Sub-dermal fluid movement
    bgTop += 0.03 * sin(t * 0.5);
    vec3 finalColor = mix(bgBottom, bgTop, uv0.y + 0.5 + 0.3 * sin(uv0.x * 2.5 + t * 0.6));

    // 3. Layer Loop
    float density = (u_layers <= 0.0) ? 3.0 : u_layers;
    float scale = (u_scale <= 0.0) ? 4.0 : u_scale * 5.0; // Larger for blobby look
    float brightness = (u_intensity <= 0.0) ? 1.5 : u_intensity;

    for(float i = 0.0; i < 5.0; i++) {
        if(i >= density) break;

        // --- Space Distortion (Domain Warping) ---
        vec2 layerUV = uv0 * scale * (1.0 + i * 0.4);

        // This math bends the coordinate space to make the movement feel like a viscous fluid
        layerUV.x += sin(layerUV.y * 1.5 + t * 0.8 + i) * 0.25;
        layerUV.y += cos(layerUV.x * 1.5 + t * 0.6 - i) * 0.25;

        // Organic drifting and rotation
        layerUV.y -= t * 0.15 * (i + 1.0); 
        layerUV *= rot(sin(t * 0.05 + i) * 0.3);

        // --- Biological Geometry ---
        vec2 bio = getOrganicBlobs(layerUV + vec2(i * 11.3, i * 22.1), t);
        float dist = bio.x;
        float activation = bio.y;

        // --- Cell Anatomy Glow ---
        // Soft outer membrane
        float membrane = smoothstep(0.45, 0.15, dist) - smoothstep(0.2, 0.0, dist);
        // Dense glowing nucleus
        float nucleus = exp(-dist * 18.0);
        // Liquid cytoplasm connecting them
        float cytoplasm = exp(-dist * 4.0) * 0.3;

        // Bio-electric pulsing based on cell activation
        float pulse = smoothstep(0.6, 1.2, sin(activation * 15.0 - t * 8.0) + activation);

        // Combine structural biology
        float structureGlow = membrane * 0.8 + nucleus * 0.6 + cytoplasm;
        float electricGlow = (nucleus * 1.5 + membrane * 0.5) * pulse;

        // 4. Coloring
        vec3 col = palette(length(uv0) * 0.3 + i * 0.2 + t * u_color_cycle + activation * 0.2);

        // High energy bioluminescence (Cyan/White)
        vec3 sparkCol = mix(col, vec3(0.5, 1.0, 0.9), 0.7);

        // Accumulate: Flesh + Electric Pulses
        finalColor += col * structureGlow * brightness * 0.6;
        finalColor += sparkCol * electricGlow * brightness * 0.9;
    }

    // 5. Post-Processing
    // Vignette for microscope feel
    float vig = 1.0 - length(uv0) * 0.6;
    finalColor *= vig;

    // Smooth Clamp / Tone Mapping 
    finalColor = smoothstep(-0.02, 1.1, finalColor);

    fragColor = vec4(finalColor, 1.0);
}
